package pe.edu.lab16.eventos;
import org.springframework.stereotype.Service;import org.springframework.http.HttpStatus;import org.springframework.web.server.ResponseStatusException;import java.util.List;
@Service public class EventoService{private final EventoRepository repo;public EventoService(EventoRepository r){repo=r;}public List<Evento> listar(){return repo.findAll();}public Evento obtener(Long id){return repo.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Evento no encontrado"));}public Evento crear(EventoRequest r){Evento e=new Evento();aplicar(e,r);return repo.save(e);}public Evento actualizar(Long id,EventoRequest r){Evento e=obtener(id);aplicar(e,r);return repo.save(e);}public void eliminar(Long id){Evento e=obtener(id);repo.delete(e);}private void aplicar(Evento e,EventoRequest r){e.setNombre(r.nombre());e.setLugar(r.lugar());e.setFecha(r.fecha());e.setCapacidad(r.capacidad());e.setEstado(r.estado());}}
